# Interactive geometric controller; uses only native actions to move the robot.
from scipy.spatial.transform import Rotation as R
import numpy as np

def refresh():
    global m,d,env,robot,eid,ctrl,down
    m,d=s.model,s.data
    env=s.env;robot=env.robots[0];eid=robot.eef_site_id['right'];ctrl=robot.part_controllers['right']
    down=np.array([[0.,1.,0.],[1.,0.,0.],[0.,0.,-1.]])
refresh()

def status():
    print('STATUS',s.check(),'EEF',d.site_xpos[eid].round(4),'BASE',d.xpos[m.body('robot0_base').id].round(3),'LIFT',d.qpos[3].round(3),'DOORS',env.door_fxtr.get_door_state(env=env),flush=True)

def action_to(p=None,rot=None,grip=1,torso=None,speed=.5):
    a=np.zeros(12);a[6]=grip;a[-1]=-1
    rb=ctrl.origin_ori
    if p is not None: a[:3]=np.clip(rb.T@(np.asarray(p)-d.site_xpos[eid])/.05,-speed,speed)
    if rot is not None: a[3:6]=np.clip(rb.T@R.from_matrix(rot@d.site_xmat[eid].reshape(3,3).T).as_rotvec()/.5,-.4,.4)
    if torso is not None:a[10]=np.clip((torso-d.qpos[3])/.05,-1,1)
    return a

def move(p,rot=None,n=100,tol=.007,torso=.28,speed=.5):
    for i in range(n):
        a=action_to(p,rot,torso=torso,speed=speed)
        s.step(a)
        if i>10 and np.linalg.norm(np.asarray(p)-d.site_xpos[eid])<tol:break
    status()
    return i+1

def hold(n=20):
    for i in range(n):s.step(action_to())
    status()

def contacts():
    print([(m.geom(c.geom1).name,m.geom(c.geom2).name,round(c.dist,4)) for c in d.contact if any(t in m.geom(c.geom1).name+m.geom(c.geom2).name for t in ['gripper0','robot0'])])

